"use client";

import { useState } from "react";
import Tesseract from "tesseract.js";

export default function Home() {
  const [file, setFile] = useState<File | null>(null);

  return (
    <main>
      <h1>Image To Word AI</h1>

      <input
        type="file"
        accept="image/*"
        onChange={(e) =>
          setFile(e.target.files?.[0] || null)
        }
      />

      {file && <p>{file.name}</p>}
    </main>
  );
}
